#!/usr/bin/env python3
"""Dependency-free static export. BASE_PATH is the repository name on GitHub Pages."""
import json, os, shutil
from html import escape as e
from pathlib import Path
from urllib.parse import quote
ROOT=Path(__file__).resolve().parent
D=json.loads((ROOT/'content.json').read_text())
B=D['business']; S=D['services']; BY={s['slug']:s for s in S}
BASE='/' + os.environ.get('BASE_PATH','').strip('/') + '/' if os.environ.get('BASE_PATH','').strip('/') else '/'
ORIGIN=os.environ.get('SITE_ORIGIN','http://localhost:8000').rstrip('/')
OUT=ROOT/'dist'
if OUT.exists():shutil.rmtree(OUT)
OUT.mkdir();shutil.copytree(ROOT/'assets',OUT/'assets')
def url(p=''):return BASE+p.lstrip('/')
def link(p,label,cls=''):return f'<a href="{e(url(p),quote=True)}" class="{cls}">{label}</a>'
def button(p,label,style=''):return link(p,e(label),'button '+style)
def serviceurl(s):return 'services/'+s['slug']+'/'
def enquiry(s):return 'contact/?service='+quote(s['name'])+'#enquiry'
def eyebrow(label):return '<p class="eyebrow">'+e(label)+'</p>'
def crumb(items):
 return '<div class="wrap"><nav class="breadcrumb" aria-label="Breadcrumb">'+link('','Home')+''.join('<span class="sep" aria-hidden="true">/</span>'+ (link(p,e(t)) if p else '<span aria-current="page">'+e(t)+'</span>') for p,t in items)+'</nav></div>'
def intro(kicker,title,text='',action=''):
 return '<div class="wrap"><div class="page-intro fade-in">'+eyebrow(kicker)+'<h1>'+title+'</h1>'+('<p class="lede">'+text+'</p>' if text else '')+action+'</div></div>'
def row(s,summary=False):
 return link(serviceurl(s),'<div><h3>'+e(s['name'])+'</h3>'+('<p>'+e(s['summary'])+'</p>' if summary else '')+'</div><span class="plus" aria-hidden="true">+</span>','service-row')
def groups(summary=False):
 return ''.join('<div class="service-group"><h3 class="group-title">'+g+'</h3>'+''.join(row(s,summary) for s in S if s['group']==g)+'</div>' for g in ['Everyday essentials','Business clarity','Your next chapter'])
def cta():
 return '<section class="cta"><div class="wrap cta-row"><div><h2>Let’s talk about<br>your business.</h2><p>Tell us what you need. We’ll put you in touch with the right person.</p></div>'+button('contact/','Start a conversation')+'</div></section>'
def header(active):
 nav=''.join(f'<a href="{url(p)}"'+(' aria-current="page"' if active==p else '')+'>'+t+'</a>' for p,t in [('services/','Our services'),('about-us/','About us'),('resources/','Resources')])
 return f'''<div class="preview">Website concept · Preview only <span>— enquiries open an email draft</span></div><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap header-row"><a class="brand" href="{url()}" aria-label="Frisby & Associates home"><img src="{url('assets/logo.webp')}" alt="Frisby & Associates" width="500" height="115"></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="navigation">Menu</button><nav class="nav" id="navigation" aria-label="Main navigation">{nav}{button('contact/','Contact us')}</nav></div></header>'''
def footer():
 return f'''<footer class="site-footer"><div class="wrap"><div class="footer-top"><div><p class="footer-title">A clear view of<br>what comes next.</p><p>Accountancy, taxation and business advice<br>for owner-managed Irish businesses.</p></div><div><h3>Explore</h3><ul>{''.join('<li>'+link(p,t)+'</li>' for p,t in [('services/','Our services'),('about-us/','About us'),('resources/','Resources & useful links'),('podcasts/','Podcasts'),('auto-enrolment-presentation/','Auto-enrolment presentation'),('contact/','Contact us')])}</ul></div><div><h3>Find us in Lucan</h3><p>Unit 11, Woodview Court, Tandy’s Lane<br>Lucan, Co. Dublin, K78 VX38, Ireland</p><p><a href="tel:{B['phoneLink']}">{B['phone']}</a><br><a href="mailto:{B['email']}">{B['email']}</a></p><p><a href="{e(B['facebook'],quote=True)}" rel="noopener noreferrer">Facebook</a> &nbsp; / &nbsp; <a href="{e(B['linkedin'],quote=True)}" rel="noopener noreferrer">LinkedIn</a></p></div></div><div class="footer-bottom"><span>© 2026 Frisby & Associates · Design preview</span>{link('privacy-policy/','Privacy & cookies')}</div><a class="back-top" href="#top">Back to top</a></div></footer>'''
PAGES=[]
def page(path,title,description,body,active='',missing=False):
 canonical=ORIGIN+url(path)
 schema={'@context':'https://schema.org','@type':'AccountingService','name':B['name'],'url':ORIGIN+BASE,'telephone':B['phoneLink'],'email':B['email'],'address':{'@type':'PostalAddress','streetAddress':'Unit 11, Woodview Court, Tandy’s Lane','addressLocality':'Lucan','addressRegion':'Co. Dublin','postalCode':'K78 VX38','addressCountry':'IE'},'openingHoursSpecification':[{'@type':'OpeningHoursSpecification','dayOfWeek':'Monday','opens':'08:00','closes':'17:00'},{'@type':'OpeningHoursSpecification','dayOfWeek':['Tuesday','Wednesday','Thursday'],'opens':'08:30','closes':'17:00'},{'@type':'OpeningHoursSpecification','dayOfWeek':'Friday','opens':'08:30','closes':'15:00'}],'sameAs':[B['facebook'],B['linkedin']]}
 html=f'''<!doctype html><html lang="en-IE"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Frisby & Associates — Preview</title><meta name="description" content="{e(description,quote=True)}"><meta name="robots" content="noindex, nofollow, noarchive"><link rel="canonical" href="{e(canonical,quote=True)}"><meta property="og:title" content="{e(title,quote=True)} | Frisby & Associates"><meta property="og:description" content="{e(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{e(canonical,quote=True)}"><meta name="theme-color" content="#242650"><link rel="icon" href="{url('assets/favicon.svg')}" type="image/svg+xml"><link rel="stylesheet" href="{url('assets/styles.css')}"><script src="{url('assets/site.js')}" defer></script>{'<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False).replace('</','<\\/')+'</script>' if path=='' else ''}</head><body id="top"{' data-missing="true"' if missing else ''}>{header(active)}<main id="main" tabindex="-1">{body}</main>{footer()}</body></html>'''
 f=OUT/'404.html' if missing else OUT/path/'index.html';f.parent.mkdir(parents=True,exist_ok=True);f.write_text(html)
 if not missing:PAGES.append(path)
# Home
home=f'''<div class="wrap hero fade-in"><div class="hero-copy">{eyebrow('For owner-managed Irish businesses')}<h1>Clear advice.<br><em>Confident decisions.</em></h1><p class="lede">Accountancy, taxation and business advice that starts with understanding your business.</p><div class="actions">{button('contact/','Talk to our team')}{button('services/','Explore our services','outline')}</div><p class="hero-note">Based in Lucan, Co. Dublin. Focused on your individual needs.</p></div><div class="hero-visual"><img src="{url('assets/advice.webp')}" width="1200" height="800" alt="Financial documents being discussed at a desk" fetchpriority="high"><p class="photo-label">A clear view of your business.<span>Accounting. Tax. Business advice.</span></p></div></div><section class="principles" aria-label="Our approach"><div class="wrap principle-row"><div><strong>Your business, understood.</strong><span>Advice tailored to your individual needs.</span></div><div><strong>Clarity from the start.</strong><span>Costs and timescales agreed up front.</span></div><div><strong>Support when it matters.</strong><span>A point of contact for financial questions.</span></div></div></section><section class="section"><div class="wrap split"><div class="section-intro">{eyebrow('What we do')}<h2>For the everyday.<br>And the big decisions.</h2><p>From accounting and payroll to planning your next chapter, find the support that fits your business.</p>{link('services/','View all services','text-link')}</div><div>{groups()}</div></div></section><section class="section about-band"><div class="wrap split"><div>{eyebrow('The Frisby approach')}<h2>Good advice begins<br>with listening.</h2><p>We specialise in progressive Irish-owned businesses. Our approach combines technical knowledge, commercial awareness and clear communication.</p>{button('about-us/','Get to know us','light')}</div><ul class="promise-list"><li><span>01</span>Understand your business before we begin.</li><li><span>02</span>Agree costs and timescales up front.</li><li><span>03</span>Work in an organised, confidential and professional way.</li></ul></div></section><section class="section"><div class="wrap"><div class="resource-heading"><div>{eyebrow('Resources & useful links')}<h2>Make room for understanding.</h2></div>{link('resources/','Explore resources','text-link')}</div><div class="resource-grid"><article class="resource-feature"><div><p class="meta">PRESENTATION · ADDED NOVEMBER 2025</p><h3>Auto-enrolment.<br>A starting point for employers.</h3><p>Watch the existing presentation, then check the latest official information for your business.</p></div>{link('auto-enrolment-presentation/','View the presentation','text-link')}</article><div><article class="resource-mini"><p class="meta">OFFICIAL SOURCES</p><h3>Useful links for Irish businesses.</h3><p>Revenue, company information and enterprise supports.</p>{link('resources/#useful-links','Find useful links','text-link')}</article><article class="resource-mini"><p class="meta">PODCAST ARCHIVE · 2020</p><h3>From the archive.</h3><p>Original conversations on COVID-era business supports, clearly dated for context.</p>{link('podcasts/','Explore the podcast archive','text-link')}</article></div></div></div></section>'''
page('','Accountancy & business advice in Lucan','Accountancy, taxation and business advisory services for owner-managed Irish businesses. Contact Frisby & Associates in Lucan, Co. Dublin.',home+cta())
# About
about=crumb([(None,'About us')])+intro('About Frisby & Associates','Your business.<br>Our starting point.','Helpful, effective and timely advice, tailored to your individual needs.')
about+=f'''<section class="section pale"><div class="wrap split"><div><h2>Clear communication.<br>Commercial understanding.</h2><p>From our offices in Lucan, we work with owner-managed Irish businesses. Our aim is to be your first point of contact when business and financial questions arise.</p><p>We combine technical skills with commercial awareness, with an emphasis on understanding what matters to your business.</p>{button('contact/','Speak to our team')}</div><div><img src="{url('assets/advice.webp')}" width="1200" height="800" alt="A discussion over financial documents" loading="lazy"><p class="meta">Illustrative image retained from the existing website.</p></div></div></section><section class="section"><div class="wrap split"><div>{eyebrow('How we work')}<h2>What you can expect.</h2><p>Our reputation is shaped by your experience of our service.</p></div><ul class="question-list"><li>A commitment to understanding your business.</li><li>Independence checks before commencing work.</li><li>Costs and timescales agreed up front.</li><li>Technical knowledge kept up to date.</li><li>An organised, confidential and transparent service.</li></ul></div></section>'''
page('about-us/','About us','Meet the approach behind Frisby & Associates: clear communication, commercial awareness and services tailored to your business.',about+cta(),'about-us/')
# Services index and individual pages
services=crumb([(None,'Our services')])+intro('Accountancy · Taxation · Consultancy','Support for every<br>business decision.','Nine services. One starting point: understanding what your business needs.')
services+='<nav class="wrap subnav" aria-label="Service categories">'+''.join(link('services/#'+g,t) for g,t in [('essentials','Everyday essentials'),('clarity','Business clarity'),('next-chapter','Your next chapter')])+'</nav>'
for g,slug,desc in [('Everyday essentials','essentials','The recurring responsibilities behind a well-run business.'),('Business clarity','clarity','Financial information to help you understand where you stand.'),('Your next chapter','next-chapter','A place to discuss growth, change and more challenging circumstances.')]:
 services+='<section class="service-overview" id="'+slug+'"><div class="wrap split"><div><h2 class="group-title">'+g+'</h2><p>'+desc+'</p></div><div>'+''.join(row(s,True) for s in S if s['group']==g)+'</div></div></section>'
page('services/','Our services','Explore nine accountancy, taxation and consultancy services offered by Frisby & Associates.',services+cta(),'services/')
for s in S:
 body=crumb([('services/','Our services'),(None,s['name'])])+intro(s['group'],e(s['name']),e(s['intro']),'<div class="actions">'+button(enquiry(s),'Discuss this service')+link('services/','All services','text-link')+'</div>')
 body+='<section class="section pale"><div class="wrap detail-layout"><div><h2>A useful place to start.</h2><p>When you contact us, these questions can help explain the support you are looking for.</p><ul class="question-list">'+''.join('<li>'+e(q)+'</li>' for q in s['questions'])+'</ul></div><aside class="aside-note"><h3>Let’s understand<br>your requirements.</h3><p>Tell us about your situation. We agree the scope, costs and timescale before work begins.</p><p>A general enquiry is enough to start. Please keep sensitive financial information out of your first message.</p><a class="text-link" href="tel:'+B['phoneLink']+'">Call '+B['phone']+'</a></aside></div></section>'
 if s['slug']=='payroll-services':body+='<section class="wrap section"><h2>For employers.</h2><p>Explore the existing auto-enrolment presentation alongside current official information.</p>'+link('auto-enrolment-presentation/','View the presentation','text-link')+'</section>'
 body+='<section class="wrap section"><h2>Related support.</h2><div class="related">'+''.join(link(serviceurl(BY[r]),e(BY[r]['name'])) for r in s['related'])+'</div></section>'
 page(serviceurl(s),s['name'],s['summary']+' Contact Frisby & Associates to discuss your requirements.',body+cta(),'services/')
# Resources
resources=crumb([(None,'Resources')])+intro('Resources & useful links','A little more clarity.','Presentations, official sources and our original archive. Check dates and ask the team about advice relevant to your circumstances.')
resources+='<nav class="wrap subnav" aria-label="Resource sections">'+link('auto-enrolment-presentation/','Auto-enrolment presentation')+link('podcasts/','Podcasts')+link('resources/#archive','2020 document archive')+'</nav>'
resources+='<section class="wrap section" id="useful-links"><div class="split"><div>'+eyebrow('Official information')+'<h2>Useful starting points.</h2><p>These independent sources provide public information. They are not a substitute for advice on your own business.</p></div><div class="useful-list"><a href="https://www.revenue.ie/en/home.aspx">Revenue Commissioners <span class="meta">— Tax information & online services</span></a><a href="https://cro.ie/">Companies Registration Office <span class="meta">— Company information & annual returns</span></a><a href="https://www.localenterprise.ie/">Local Enterprise Office <span class="meta">— Business supports & advice</span></a></div></div></section>'
resources+='<section class="pale section"><div class="wrap resource-grid"><article class="resource-feature"><p class="meta">PRESENTATION · NOVEMBER 2025</p><h3>Auto-enrolment for employers.</h3><p>The presentation published on the original website, with a link to current official information.</p>'+link('auto-enrolment-presentation/','View presentation','text-link')+'</article><article class="resource-feature"><p class="meta">AUDIO ARCHIVE · 2020</p><h3>The original podcasts.</h3><p>Two episodes discussing COVID-era employer supports. Retained as historical material.</p>'+link('podcasts/','Browse podcasts','text-link')+'</article></div></section>'
resources+='<section class="wrap section" id="archive"><div class="split"><div>'+eyebrow('Document archive · 2020')+'<h2>Preserved.<br>Clearly dated.</h2><p>Original downloads remain available here, without leaving this website.</p></div><div><div class="notice"><strong>Historical material — not current guidance.</strong>These documents relate to COVID-era schemes and supports in 2020. They may be superseded. Do not rely on them for current eligibility, rates or obligations.</div>'+''.join('<div class="document-row"><div><h3>'+e(d['name'])+'</h3><span class="meta">'+d['date']+' · PDF</span></div>'+link('assets/archive/'+d['file'],'Open PDF','text-link')+'</div>' for d in D['documents'])+'</div></div></section>'
page('resources/','Resources & useful links','Explore official Irish business information, the auto-enrolment presentation and clearly dated 2020 document and podcast archives.',resources+cta(),'resources/')
# Podcasts
pod=crumb([('resources/','Resources'),(None,'Podcasts')])+intro('The podcast archive','Conversations<br>from the archive.','Original Frisby & Associates recordings on employer supports in 2020.')+'<section class="wrap"><div class="notice"><strong>Recorded in 2020 — historical material.</strong>These episodes discuss COVID-era schemes. They are not current tax or payroll guidance.</div>'
for i,p in enumerate(D['podcasts']):
 pod+=f'''<article class="episode"><span class="episode-number">{p['number']}</span><div><p class="meta">RECORDED {p['date'].upper()}</p><h2>{e(p['title'])}</h2><div class="player-actions"><button class="button outline" type="button" data-media="{e(p['embed'],quote=True)}" data-target="player-{i}" data-title="{e(p['title'],quote=True)}">Load audio player</button><a class="text-link" href="{e(p['url'],quote=True)}" rel="noopener noreferrer">Listen on the original platform</a></div><p class="player-help">Loading the player connects to a third-party audio service. If it does not load, use the original-platform link.</p><div id="player-{i}"></div></div></article>'''
pod+='</section><section class="wrap section"><h2>Looking for today’s answer?</h2><p>Start with official sources or speak to the team about your business.</p>'+link('resources/#useful-links','Find useful links','text-link')+'</section>'
page('podcasts/','Podcast archive','Listen to the two original Frisby & Associates podcasts, recorded in July and August 2020.',pod+cta(),'resources/')
# Video
video=crumb([('resources/','Resources'),(None,'Auto-enrolment presentation')])+intro('Employer resources','Auto-enrolment<br>presentation.','The original presentation for employers and payroll operators, published on the website in November 2025.')
video+=f'''<section class="wrap"><div class="video-panel" id="presentation"><p class="meta">FRISBY & ASSOCIATES · EMPLOYER PRESENTATION</p><h2>Understanding<br>auto-enrolment.</h2><button class="button light" type="button" data-media="https://www.youtube-nocookie.com/embed/tpWEg-lV8Q0" data-target="presentation" data-title="Frisby & Associates auto-enrolment presentation">Load video</button></div><p class="player-help">Loading the video connects to YouTube. You can also <a href="https://www.youtube.com/watch?v=tpWEg-lV8Q0">watch the original video on YouTube</a>.</p></section><section class="wrap section"><div class="detail-layout"><div><h2>Check the latest information.</h2><p>The presentation was prepared ahead of January 2026. Requirements and guidance may have changed since it was recorded.</p><p>Use the official government information for the latest position and contact us to discuss your payroll arrangements.</p><a class="text-link" href="https://myfuturefund.ie/">Official auto-enrolment information</a></div><aside class="aside-note"><h3>A question about payroll?</h3><p>Tell us about your business and the support you need.</p>{button('contact/?service=Payroll%20Services#enquiry','Discuss payroll')}</aside></div></section>'''
page('auto-enrolment-presentation/','Auto-enrolment presentation','Watch the existing Frisby & Associates employer presentation and check current official auto-enrolment information.',video,'resources/')
