contact=crumb([(None,'Contact us')])+intro('Contact Frisby & Associates','Start with<br>a conversation.','Tell us a little about your business and the support you need. We’ll put you in touch with the right person.')
options=''.join('<option>'+e(s['name'])+'</option>' for s in S)
