page('404.html','Page not found','Find your way back to Frisby & Associates services and contact information.',missing,missing=True)
# noindex is the indexing control. Allow crawlers to see it rather than blocking access.
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\n# Every HTML page carries noindex, nofollow, noarchive. Preview only.\n')
(OUT/'.nojekyll').touch()
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+e(ORIGIN+url(p))+'</loc></url>' for p in PAGES)+'</urlset>')
